// ************
// Types
// ************

import '@dev.hiconic/gm_root-model';
import '@dev.hiconic/gm_reason-model';
import '@dev.hiconic/gm_essential-reason-model';
import '@dev.hiconic/gm_gm-core-api';

import { T } from '@dev.hiconic/hc-js-base';

export declare namespace meta {
	const groupId: string;
	const artifactId: string;
	const version: string;
}

export import AuthenticationFailure = T.com.braintribe.gm.model.security.reason.AuthenticationFailure;
export import Forbidden = T.com.braintribe.gm.model.security.reason.Forbidden;
export import InvalidCredentials = T.com.braintribe.gm.model.security.reason.InvalidCredentials;
export import InvalidSession = T.com.braintribe.gm.model.security.reason.InvalidSession;
export import MissingCredentials = T.com.braintribe.gm.model.security.reason.MissingCredentials;
export import MissingSession = T.com.braintribe.gm.model.security.reason.MissingSession;
export import SecondFactorRequired = T.com.braintribe.gm.model.security.reason.SecondFactorRequired;
export import SecurityReason = T.com.braintribe.gm.model.security.reason.SecurityReason;
export import SessionExpired = T.com.braintribe.gm.model.security.reason.SessionExpired;
export import SessionNotFound = T.com.braintribe.gm.model.security.reason.SessionNotFound;

declare module '@dev.hiconic/hc-js-base' {

	namespace T.com.braintribe.gm.model.security.reason {

		const AuthenticationFailure: hc.reflection.EntityType<AuthenticationFailure>;
		type AuthenticationFailure = SecurityReason &
		  Entity<"com.braintribe.gm.model.security.reason.AuthenticationFailure">;

		const Forbidden: hc.reflection.EntityType<Forbidden>;
		type Forbidden = SecurityReason &
		  Entity<"com.braintribe.gm.model.security.reason.Forbidden">;

		const InvalidCredentials: hc.reflection.EntityType<InvalidCredentials>;
		type InvalidCredentials = AuthenticationFailure &
		  Entity<"com.braintribe.gm.model.security.reason.InvalidCredentials">;

		const InvalidSession: hc.reflection.EntityType<InvalidSession>;
		type InvalidSession = AuthenticationFailure &
		  Entity<"com.braintribe.gm.model.security.reason.InvalidSession">;

		const MissingCredentials: hc.reflection.EntityType<MissingCredentials>;
		type MissingCredentials = AuthenticationFailure &
		  Entity<"com.braintribe.gm.model.security.reason.MissingCredentials">;

		const MissingSession: hc.reflection.EntityType<MissingSession>;
		type MissingSession = MissingCredentials &
		  Entity<"com.braintribe.gm.model.security.reason.MissingSession">;

		const SecondFactorRequired: hc.reflection.EntityType<SecondFactorRequired>;
		type SecondFactorRequired = SecurityReason &
		  Entity<"com.braintribe.gm.model.security.reason.SecondFactorRequired", {
			redirectUrl: string;
			tokenId: string;
		}>;

		const SecurityReason: hc.reflection.EntityType<SecurityReason>;
		type SecurityReason = T.com.braintribe.gm.model.reason.Reason &
		  Entity<"com.braintribe.gm.model.security.reason.SecurityReason">;

		const SessionExpired: hc.reflection.EntityType<SessionExpired>;
		type SessionExpired = InvalidSession &
		  Entity<"com.braintribe.gm.model.security.reason.SessionExpired">;

		const SessionNotFound: hc.reflection.EntityType<SessionNotFound>;
		type SessionNotFound = InvalidSession &
		  Entity<"com.braintribe.gm.model.security.reason.SessionNotFound">;

	}

}
